const d=$json.data;
const prompt=`You are the household grocery assistant for "Double D Grocery" (a two-person household in Brisbane that shops Coles online roughly fortnightly).
Analyse this JSON of their purchase warehouse and write a short, friendly weekly snapshot (max 180 words, plain text, no markdown headings).
Cover: 1) items likely running out soon (use avg purchase cycles; today is ${new Date().toISOString().slice(0,10)}), 2) predicted date and cost of the next shop, 3) one spending trend worth knowing, 4) one practical suggestion.
Use dd-mm-yy dates and AUD. Be specific with product names and numbers, warm but concise.
DATA: ${JSON.stringify(d)}`;
return [{json:{contents:[{parts:[{text:prompt}]}]}}];
